from pathlib import Path
import json
import re

ROOT = Path(__file__).resolve().parents[2]
DRAFTS = ROOT / 'freeze' / 'drafts'
BLOCKS = ['Event', 'Participation', 'Public Action', 'Judgment & Remedy', 'Opinion Topology', 'Holdings', 'Precedent Treatment', 'Law After Decision', 'Separate Writings', 'Procedure After Action', 'Source Notes']
VOTES = []

def record(filename, identity, result, internal, public, vote):
    assert list(public) == BLOCKS
    text = f'**Case and dockets:** {identity}\n**Event and date:** Merits decision, 1995-01-18; October Term 1994, chunk 2.\n**Result:** {result}\n**Version / lineage:** Initial Canonical Decision Record; supersedes no completed adjudication. File preserved under the user\'s no-Git instruction; no Git operation or repository commit is claimed.\n\n'
    text += internal.strip() + '\n\n## Controlling holdings\n\n' + public['Holdings'] + '\n\n## Public Projection\n\n'
    text += '\n\n'.join('## ' + k + '\n\n' + v.strip() for k,v in public.items()) + '\n'
    (DRAFTS / filename).write_text(text, encoding='utf-8')
    vote['filename'] = filename
    VOTES.append(vote)

